<script setup lang="ts">
import {onMounted, ref} from "vue"
import {useRoute} from "vue-router"
import type {BusinessOfferingResponseDTO} from "../../../contracts/index.ts"
import {setActiveBusinessProfileId, userShellApi} from "../api/userShellApi.ts"
import AppButton from "../components/AppButton.vue"
import AppStatus from "../components/AppStatus.vue"
import BusinessPricingRuleEditor from "../components/BusinessPricingRuleEditor.vue"
import BusinessServiceSetupStepper from "../components/BusinessServiceSetupStepper.vue"
import ContextSwitcher from "../components/ContextSwitcher.vue"
import TaskSurface from "../components/TaskSurface.vue"

type SchemaRow = Record<string, unknown>
type SchemaDraft = {demandFields: SchemaRow[]; options: SchemaRow[]; pricingRules: SchemaRow[]}

const steps = ["Basics", "Time & capacity", "Customer questions", "Price rules", "Resources", "Preview"]
const route = useRoute()
const currentStep = ref(0)
const offerings = ref<BusinessOfferingResponseDTO[]>([])
const offeringDraft = ref<BusinessOfferingResponseDTO | null>(null)
const schemaDraft = ref<SchemaDraft>({demandFields: [], options: [], pricingRules: []})
const selectedOfferingId = ref<number | null>(null)
const loading = ref(true)
const saving = ref(false)
const error = ref("")
const profileId = () => Number(route.query.businessId ?? sessionStorage.getItem("activeBusinessProfileId"))
const value = (row: SchemaRow, camel: string, snake: string, fallback: unknown = "") => row[camel] ?? row[snake] ?? fallback
const normalizeFields = (rows: SchemaRow[]) => rows.map((row, index) => ({fieldKey: value(row, "fieldKey", "field_key"), label: value(row, "label", "label"), description: value(row, "description", "description"), valueType: value(row, "valueType", "value_type", "TEXT"), required: Boolean(value(row, "required", "required", false)), customerVisible: Boolean(value(row, "customerVisible", "customer_visible", true)), ownerVisible: Boolean(value(row, "ownerVisible", "owner_visible", true)), retentionDays: value(row, "retentionDays", "retention_days", null), active: Boolean(value(row, "active", "active", true)), sortOrder: Number(value(row, "sortOrder", "sort_order", index))}))
const normalizeOptions = (rows: SchemaRow[]) => rows.map((row, index) => ({optionKey: value(row, "optionKey", "option_key"), label: value(row, "label", "label"), description: value(row, "description", "description"), valueType: value(row, "valueType", "value_type", "TEXT"), required: Boolean(value(row, "required", "required", false)), active: Boolean(value(row, "active", "active", true)), sortOrder: Number(value(row, "sortOrder", "sort_order", index))}))
const normalizeRules = (rows: SchemaRow[]) => rows.map((row, index) => ({ruleKey: value(row, "ruleKey", "rule_key"), ruleType: value(row, "ruleType", "rule_type", "BASE"), billingUnit: value(row, "billingUnit", "billing_unit", "BOOKING"), amount: value(row, "amount", "amount", null), currency: value(row, "currency", "currency", "CHF"), active: Boolean(value(row, "active", "active", true)), sortOrder: Number(value(row, "sortOrder", "sort_order", index))}))
const selectOffering = async () => { if (!selectedOfferingId.value) return; offeringDraft.value = offerings.value.find(item => item.id === selectedOfferingId.value) ?? null; const ownerSchema = await userShellApi.getBusinessOfferingSchema(selectedOfferingId.value) as unknown as Record<string, SchemaRow[]>; schemaDraft.value = {demandFields: normalizeFields(ownerSchema.demandFields ?? []), options: normalizeOptions(ownerSchema.options ?? []), pricingRules: normalizeRules(ownerSchema.pricingRules ?? [])} }
const load = async () => { loading.value = true; error.value = ""; try { if (profileId()) setActiveBusinessProfileId(profileId()); offerings.value = (await userShellApi.getBusinessOfferings()).items; const requestedOfferingId = Number(route.query.offeringId); selectedOfferingId.value = selectedOfferingId.value ?? offerings.value.find(item => item.id === requestedOfferingId)?.id ?? offerings.value[0]?.id ?? null; await selectOffering() } catch { error.value = "Could not load service configuration." } finally { loading.value = false } }
const saveOfferingRules = async () => { if (!offeringDraft.value) return; saving.value = true; error.value = ""; try { await userShellApi.updateBusinessOffering(offeringDraft.value.id, offeringDraft.value as any); await load() } catch { error.value = "Could not save service rules." } finally { saving.value = false } }
const saveSchema = async () => { if (!selectedOfferingId.value) return; saving.value = true; error.value = ""; try { await userShellApi.replaceBusinessOfferingSchema(selectedOfferingId.value, schemaDraft.value); await selectOffering() } catch { error.value = "Could not save customer questions or price rules." } finally { saving.value = false } }
const addQuestion = () => schemaDraft.value.demandFields.push({fieldKey: "", label: "", description: "", valueType: "TEXT", required: false, customerVisible: true, ownerVisible: true, active: true, sortOrder: schemaDraft.value.demandFields.length})
const removeQuestion = (index: number) => { schemaDraft.value.demandFields.splice(index, 1); schemaDraft.value.demandFields.forEach((field, fieldIndex) => field.sortOrder = fieldIndex) }
const addOption = () => schemaDraft.value.options.push({optionKey: "", label: "", description: "", valueType: "TEXT", required: false, active: true, sortOrder: schemaDraft.value.options.length})
const removeOption = (index: number) => { schemaDraft.value.options.splice(index, 1); schemaDraft.value.options.forEach((option, optionIndex) => option.sortOrder = optionIndex) }
const schemaStep = () => currentStep.value === 2 || currentStep.value === 3
onMounted(() => void load())
</script>

<template>
  <TaskSurface mode="act" label="Service setup"><section class="service-setup"><header><p class="eyebrow">Business / Service setup</p><div class="service-setup__title-row"><div><h1>Configure a service</h1><p>Set only what customers need to choose a time and understand the price. The backend still validates every booking and quote.</p></div><ContextSwitcher v-if="offerings.length" :model-value="selectedOfferingId" :options="offerings.map(item => ({id: item.id, label: item.title}))" label="Service" empty-label="Choose service" @update:model-value="async value => { selectedOfferingId = value === null ? null : Number(value); await selectOffering() }" /></div></header><AppStatus v-if="loading" message="Loading service configuration." busy /><AppStatus v-else-if="error && !offeringDraft" :message="error" tone="error" retry @retry="load" /><template v-else-if="offeringDraft"><BusinessServiceSetupStepper :steps="steps" :current="currentStep" @select="currentStep = $event" /><section class="setup-panel"><template v-if="currentStep === 0"><h2>Service basics</h2><p>Choose the type of appointment customers are booking.</p><label>How is this service delivered?<select v-model="offeringDraft.fulfillmentMode"><option value="EXACT_APPOINTMENT">At a specific time</option><option value="CAPACITY_WINDOW">A shared time window</option><option value="FIELD_SERVICE">At the customer’s place</option><option value="ALL_DAY_STAY">A full day or stay</option></select></label></template><template v-else-if="currentStep === 1"><h2>Time and capacity</h2><p>Use these only when one booking differs from your normal appointment length or group size.</p><div class="setup-grid"><label>Time increments (minutes)<input v-model.number="offeringDraft.durationIncrementMinutes" type="number" min="1"></label><label>Minimum people or items<input v-model.number="offeringDraft.minimumQuantity" type="number" min="1"></label><label>Maximum people or items<input v-model.number="offeringDraft.maximumQuantity" type="number" min="1"></label></div></template><template v-else-if="currentStep === 2"><h2>Customer questions</h2><p>Ask only information you genuinely need before the appointment. These answers are collected during booking.</p><div class="schema-list"><article v-for="(field, index) in schemaDraft.demandFields" :key="index" class="schema-card"><label><span>Question {{ index + 1 }}</span><input v-model="field.label" placeholder="e.g. What should we know before you arrive?"></label><label>Answer type<select v-model="field.valueType"><option value="TEXT">Short answer</option><option value="LONG_TEXT">Long answer</option><option value="BOOLEAN">Yes or no</option><option value="DATE">Date</option></select></label><label class="schema-card__check"><input v-model="field.required" type="checkbox"> Required</label><AppButton tone="danger" @click="removeQuestion(index)">Remove</AppButton></article><p v-if="!schemaDraft.demandFields.length" class="empty-copy">No questions yet. Most services can start without any.</p></div><AppButton tone="secondary" @click="addQuestion">Add customer question</AppButton><h3>Optional choices</h3><p>Use this for a simple choice the customer can make, such as a preferred scent or add-on.</p><div class="schema-list"><article v-for="(option, index) in schemaDraft.options" :key="index" class="schema-card"><label><span>Choice {{ index + 1 }}</span><input v-model="option.label" placeholder="e.g. Preferred scent"></label><label>Answer type<select v-model="option.valueType"><option value="TEXT">Short answer</option><option value="BOOLEAN">Yes or no</option></select></label><label class="schema-card__check"><input v-model="option.required" type="checkbox"> Required</label><AppButton tone="danger" @click="removeOption(index)">Remove</AppButton></article><p v-if="!schemaDraft.options.length" class="empty-copy">No optional choices yet.</p></div><AppButton tone="secondary" @click="addOption">Add optional choice</AppButton></template><template v-else-if="currentStep === 3"><h2>Price rules</h2><p>Your base price stays on the service. Add a rule only for a predictable extra charge.</p><BusinessPricingRuleEditor v-model:rules="schemaDraft.pricingRules" /></template><template v-else-if="currentStep === 4"><h2>Resources</h2><p>Most appointment businesses do not need this. Resource allocation for staff, rooms, and equipment will return as a dedicated setup when it is ready.</p><p class="empty-copy">For now, keep availability simple with your working hours and service capacity.</p></template><template v-else><h2>Customer preview</h2><p>This is the simple sequence customers will follow.</p><ol><li>{{ offeringDraft.title }}</li><li>Choose a suitable date and time</li><li>Answer only the questions you added</li><li>Review the price and booking conditions</li></ol></template><AppStatus v-if="error" :message="error" tone="error" /><footer class="setup-actions"><AppButton type="button" tone="secondary" :disabled="currentStep === 0" @click="currentStep--">Back</AppButton><AppButton v-if="currentStep < steps.length - 1" type="button" tone="secondary" @click="currentStep++">Next</AppButton><AppButton type="button" tone="primary" :loading="saving" @click="schemaStep() ? saveSchema() : saveOfferingRules()">{{ schemaStep() ? "Save booking details" : "Save service rules" }}</AppButton></footer></section></template></section></TaskSurface>
</template>

<style scoped>
.service-setup{display:grid;gap:var(--space-3);max-width:70rem}.eyebrow{margin:0 0 var(--space-1);color:var(--text-soft);font-size:var(--text-size-label);font-weight:var(--text-weight-semibold);letter-spacing:var(--tracking-label);text-transform:uppercase}.service-setup h1,.service-setup h2,.service-setup h3,.service-setup p{margin:0}.service-setup h1{font-size:var(--text-size-page-title);letter-spacing:var(--tracking-tight)}.service-setup p{color:var(--text-muted);line-height:1.5}.service-setup__title-row{display:flex;align-items:end;justify-content:space-between;gap:var(--space-3)}.setup-panel{display:grid;gap:var(--space-3);padding:var(--space-4);border:1px solid var(--border-subtle);border-radius:var(--radius-surface);background:var(--surface-base)}.setup-panel label{display:grid;gap:var(--space-1);color:var(--text-muted);font-size:var(--text-size-meta);font-weight:var(--text-weight-semibold)}.setup-panel input,.setup-panel select{border:1px solid var(--control-border);border-radius:var(--radius-control);padding:var(--space-2);background:var(--control-bg);color:var(--control-ink);font:inherit}.setup-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:var(--space-2)}.setup-panel ol{display:grid;gap:var(--space-2);margin:0;padding-left:1.2rem}.setup-panel li{padding-bottom:var(--space-2);border-bottom:1px solid var(--border-subtle)}.schema-list{display:grid;gap:var(--space-2)}.schema-card{display:grid;grid-template-columns:minmax(14rem,2fr) minmax(10rem,1fr) auto auto;gap:var(--space-2);align-items:end;padding:var(--space-3);border:1px solid var(--border-subtle);border-radius:var(--radius-control)}.schema-card__check{display:flex!important;align-items:center;gap:var(--space-1)}.schema-card__check input{width:auto}.empty-copy{font-size:var(--text-size-meta)}.setup-actions{display:flex;justify-content:space-between;gap:var(--space-2);flex-wrap:wrap}.setup-actions>:last-child{margin-left:auto}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@media(max-width:800px){.service-setup__title-row{align-items:start;flex-direction:column}.setup-grid,.schema-card{grid-template-columns:1fr 1fr}.setup-actions>:last-child{margin-left:0}}@media(max-width:520px){.setup-grid,.schema-card{grid-template-columns:1fr}}
</style>
